const currentTimeISO = new Date().toISOString();

try {
  const rawText = $input.first().json.text || $input.first().json.output || '{}';
  let aiData = {};
  try { aiData = JSON.parse(rawText); } catch (e) { aiData = {}; }

  const originalData = $('Webhook').first().json;
  const complaintTextRaw = originalData.body.body.data.fields[2].value;
  const complaintText = complaintTextRaw.toLowerCase();

  // ✅ Word-boundary safe matching — avoids "urgent" hitting "urgently"
  function matchesAny(text, keywords) {
    return keywords.some(word => {
      // Escape special regex characters in keyword
      const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(`\\b${escaped}\\b`, 'i');
      return regex.test(text);
    });
  }

  // ✅ Genuinely aggressive/escalatory angry keywords only
  const angryKeywords = [
    'furious', 'outraged', 'livid', 'pissed',
    'worst', 'terrible', 'horrible', 'awful', 'pathetic', 'useless',
    'disgusting', 'unacceptable', 'shameful', 'absurd', 'incompetent',
    'scam', 'fraud', 'fake', 'cheated', 'lied', 'dishonest', 'misleading',
    'trash', 'garbage', 'nonsense',
    'legal action', 'lawyer', 'sue', 'consumer court',
    'police complaint', 'court notice', 'legal notice', 'cyber crime',
    'file a complaint', 'report you', 'ombudsman',
    'bad review', '1 star', 'one star', 'negative review',
    'expose this', 'viral', 'tell everyone', 'share everywhere',
    'post publicly', 'social media',
    'never again', 'never buying again', 'lost trust',
    'full refund', 'refund immediately', 'money back', 'return my money',
    'cancel immediately', 'take it back',
    'how dare you', 'this is ridiculous', 'this is unacceptable',
    'highly disappointed', 'extremely disappointed', 'extremely unhappy',
    'fed up', 'sick of this', 'had enough', 'done with this',
    'wasting my time', 'waste of money',
    'manager immediately', 'escalate this', 'higher authority',
    'fix this asap', 'take action immediately', 'instant refund'
  ];

  // ✅ Frustrated = complaint tone, not rage
  const frustratedKeywords = [
    'frustrated', 'disappointed', 'annoyed', 'irritated', 'upset',
    'issue', 'problem', 'delay', 'delayed', 'slow', 'not happy',
    'concern', 'confused', 'unclear', 'waiting', 'still waiting',
    'no response', 'no reply', 'no update', 'not resolved',
    'still not resolved', 'follow up', 'please check',
    'need update', 'not working', 'does not work', 'stopped working',
    'damaged', 'broken', 'defective', 'faulty',
    'wrong product', 'missing item', 'poor packaging',
    'late delivery', 'not delivered', 'bad service',
    'urgent', 'urgently', 'as soon as possible', 'immediately',
    'please help', 'need help', 'replace', 'replacement', 'refund'
  ];

  // ✅ ALL CAPS detection (exclude short all-caps like "OK", "TV")
  const isAllCaps =
    complaintTextRaw.replace(/\s/g, '').length > 15 &&
    complaintTextRaw === complaintTextRaw.toUpperCase();

  // ✅ Repeated punctuation as anger signal
  const hasRepeatedPunctuation = /[!?]{2,}/.test(complaintTextRaw);

  let sentiment = 'Neutral';

  if (isAllCaps || hasRepeatedPunctuation || matchesAny(complaintText, angryKeywords)) {
    sentiment = 'Angry';
  } else if (matchesAny(complaintText, frustratedKeywords)) {
    sentiment = 'Frustrated';
  }

  return {
    json: {
      timestamp_utc: currentTimeISO,
      Name: originalData.body.body.data.fields[0].value,
      Contact: originalData.body.body.data.fields[1].value,
      Description: complaintTextRaw,
      Category: aiData.category || 'General',
      Sentiment: sentiment,
      SuggestedAction: aiData.suggestedAction || 'Review manually',
      DraftResponse: aiData.draftResponse || 'We will get back to you shortly.'
    }
  };

} catch (error) {
  const originalData = $('Webhook').first().json;
  return {
    json: {
      timestamp_utc: new Date().toISOString(),
    Name: (originalData.body && originalData.body.body && originalData.body.body.data && originalData.body.body.data.fields && originalData.body?.body?.data?.fields?.[0]?.value) || 'Unknown',

      Contact: (originalData.body?.body?.data?.fields?.[1]?.value) || '',
  Description: (originalData.body?.body?.data?.fields?.[2]?.value) || '',
      Sentiment: 'Neutral',
      SuggestedAction: 'Review manually — processing error',
      DraftResponse: 'We have received your complaint and will respond shortly.',
      Error: error.message
    }
  };
}
